from collections import deque
from typing import List

def waterJugProblem(capacities: List[int], initial: List[int], target: List[int]) -> int:
    start, goal = tuple(initial), tuple(target)
    if sum(start) != sum(goal):
        return -1
    dist = {start: 0}
    q = deque([start])
    while q:
        state = q.popleft()
        if state == goal:
            return dist[state]
        for i in range(4):
            if state[i] == 0:
                continue
            for j in range(4):
                if i == j:
                    continue
                pour = min(state[i], capacities[j] - state[j])
                if pour == 0:
                    continue
                nxt = list(state)
                nxt[i] -= pour
                nxt[j] += pour
                nxt = tuple(nxt)
                if nxt not in dist:
                    dist[nxt] = dist[state] + 1
                    q.append(nxt)
    return -1
